INSERT INTO public.users VALUES ('24', '1', 'naomisc', 'madrasa', '3', 'נעמי שור', 'naomi.schor@gmail.com', '1', NULL, '0', 'שמי נעמי שור ואני בוגרת הטכניון במדעי המחשב וגרה בחיפה. התחלתי ללמוד ערבית מדוברת בבי״ס דיוואן, והמשכתי במתנ״ס בחיפה. חיפה כידוע עיר מעורבת, ונראה לי טבעי להיות מסוגלת לתקשר עם שכני בלשונם. אין כמו שפה משותפת כדי להכיר את הזולת ולהסיר מחיצות.', '2', '1', '2013-03-28T00:00:00Z', '15', '1', '0', '0', '0', '0', '0', NULL, NULL, NULL, NULL, NULL, NULL);
