INSERT INTO public.users VALUES ('32', '77', 'dor.witlin', 'madrasa', '7', 'דור ויטלין', 'id32frozen@rothfarb.com', '1', NULL, '0', 'בן 23 מהוד השרון, סטודנט לתקשורת במרכז הבינתחומי הרצליה. לדור ניסיון רב בתרגום ובהוראת השפה הערבית הספרותית והמדוברת במסגרות צבאיות שונות. הוא מלמד ערבית ליחידים ולקבוצות החל מרמת מתחילים (לרבות הכנה לבגרות 5 יח"ל) ועד לרמת מתקדמים. דור משמש כרכז קמפוס ערבית בלינגולרן, ביה"ס המקוון ללימוד שפות.', '1', '1', '2013-09-12T00:00:00Z', '15', '1', '1', '0', '0', '0', '0', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.users VALUES ('33', '1', 'baruchi', 'madrasa', '3', 'דולי ברוך', 'odeliabaruchi@gmail.com', '1', NULL, '0', 'החיבור שלי עם ערבית מדוברת הוא בערך מאז שנולדתי... הוריי עלו ממצרים ומגיל 12 אני לומדת ערבית ועובדת עם ערבית. ההתמחות שלי היא יותר ערבית ספרותית, אך אני מבינה  ומדברת גם ערבית מדוברת.', '2', '1', '2013-09-15T00:00:00Z', '15', '1', '0', '0', '0', '0', '0', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.users VALUES ('34', '77', 'epilo', 'madrasa', '3', 'אלי פילו', 'id34frozen@rothfarb.com', '1', NULL, '0', 'עוסק הרבה בהיסטורית יהודי מרוקו וברשותי אתר עם כתבות רבות אודות יהודי מרוקו וכמה קטגוריות בנושא האסלאם. 
כתובת האתר היא 
www.moreshet-morocco.com 
פעיל בכמה מרכזים להפצת מורשת יהודי מרוקו ומנהגיהם. אני קורא וכותב את השפה הערבית הקלאסית - &#39;הפוסחא&#39; באופן שוטף, ועברתי קורס באוניברסיטה הפתוחה לערבית מדוברת.', '1', '0', '2013-09-20T00:00:00Z', '15', '1', '0', '0', '0', '0', '0', NULL, NULL, NULL, NULL, NULL, NULL);
