INSERT INTO public.users VALUES ('39', '77', 'ilan1989', 'madrasa', '3', 'אילן אדרי', 'id39frozen@rothfarb.com', '1', NULL, '0', 'יליד 89 ממוצקין.
התחלתי לשמוע מוזיקה ערבית בגיל 17 ומשם התאהבתי בשפה. בצבא עשיתי קורס מתשאלים שזה בעצם חוקר בערבית. היום אני משתדל לדבר בערבית כמה שיותר, אם זה עם דרוזים, אנשים מטוניס ואחרים...', '1', '1', '2013-11-04T00:00:00Z', '15', '1', '0', '0', '0', '0', '0', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.users VALUES ('40', '1', 'menta27', 'madrasa', '3', 'איילת אביטל מגן', 'menta27@gmail.com', '1', NULL, '0', 'פסיכיאטרית ילדים שעובדת גם עם ילדים ערבים. החלטתי סוף סוף ללמוד את השפה.', '2', '1', '2013-12-12T00:00:00Z', '15', '1', '0', '0', '0', '0', '0', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.users VALUES ('41', '1', 'havardi', 'madrasa', '3', 'שי הוורדי', 'shay@allalouf.com', '1', NULL, '0', 'שמי שי הוורדי, נשוי + 2 מקסימים. 
אני מנהל רשת מחשבים בחברת אלאלוף ספנות ואני נמצא הרבה בדרכים.
לומד ערבית מדוברת באוניברסיטה הפתוחה.

החיבור שלי לערבית הוא דרך אבא שלי. אבא שלי תימני דובר ערבית, ספרדית, צרפתית. מאוד מושכת אותי השפה ואני מעוניין להגיע לרמה של לקרוא עיתון ולראות ולשמוע סרטים ומוסיקה.

בשלב מאוחר יותר אני מעוניין ליצור קשר עם העולם הערבי ברמה עסקית וביצירת קשרים.', '1', '1', '2013-12-25T00:00:00Z', '15', '1', '0', '0', '0', '0', '0', NULL, NULL, NULL, NULL, NULL, NULL);
